inline void enc_part(std::string& out, const Part& v, int depth) {
    if (wire_name(v.kind).empty()) throw Refusal("bad_enum", 0);
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "kind");
    out += ": ";
    esc(out, std::string(wire_name(v.kind)));
    if (!v.text.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "text");
        out += ": ";
        esc(out, v.text);
    }
    if (!v.digest.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "digest");
        out += ": ";
        esc(out, v.digest);
    }
    if (!v.media_type.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "media_type");
        out += ": ";
        esc(out, v.media_type);
    }
    if (!v.call_id.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "call_id");
        out += ": ";
        esc(out, v.call_id);
    }
    if (!v.name.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "name");
        out += ": ";
        esc(out, v.name);
    }
    if (!v.arguments.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "arguments");
        out += ": ";
        esc(out, v.arguments);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

