inline void enc_options(std::string& out, const Options& v, int depth) {
    out += '{';
    bool first = true;
    if (v.max_output != 0) {
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "max_output");
        out += ": ";
        num(out, v.max_output);
    }
    if (v.temperature.has_value()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "temperature");
        out += ": ";
        enc_temperature(out, *v.temperature, depth + 1);
    }
    if (!v.stop.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "stop");
        out += ": ";
        strs(out, v.stop, depth + 1);
    }
    if (!v.json_schema.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "json_schema");
        out += ": ";
        esc(out, v.json_schema);
    }
    if (!first) { out += '\n'; pad(out, depth); }
    out += '}';
}

inline void enc_request(std::string& out, const Request& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "model");
    out += ": ";
    esc(out, v.model);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "messages");
    out += ": ";
    enc_list<Message>(out, v.messages, depth + 1, enc_message);
    if (!v.tools.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "tools");
        out += ": ";
        enc_list<Tool>(out, v.tools, depth + 1, enc_tool);
    }
    if (v.options.has_value()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "options");
        out += ": ";
        enc_options(out, *v.options, depth + 1);
    }
    if (!v.extensions.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "extensions");
        out += ": ";
        strmap(out, v.extensions, depth + 1);
    }
    if (!v.required_extensions.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "required_extensions");
        out += ": ";
        strs(out, v.required_extensions, depth + 1);
    }
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "guarantees");
    out += ": ";
    strs(out, v.guarantees, depth + 1);
    if (!v.credential.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "credential");
        out += ": ";
        esc(out, v.credential);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

