inline Part decode_part(Reader& r) {
    if (r.at() != '{') r.refuse("wrong_type");
    r.enter();
    ++r.pos;
    Part v;
    std::optional<std::string> wire_kind;
    std::uint32_t seen = 0;
    r.skip_ws();
    if (r.at() != '}') {
        for (;;) {
            r.skip_ws();
            if (r.at() != '"') r.refuse("malformed");
            const std::string key = r.str();
            r.skip_ws();
            if (r.at() != ':') r.refuse("malformed");
            ++r.pos;
            r.skip_ws();
            if (key == "kind") {
                if (seen & 1u) r.refuse("duplicate_field");
                seen |= 1u;
                wire_kind = r.str();
            } else if (key == "text") {
                if (seen & 2u) r.refuse("duplicate_field");
                seen |= 2u;
                v.text = r.str();
            } else if (key == "digest") {
                if (seen & 4u) r.refuse("duplicate_field");
                seen |= 4u;
                v.digest = r.str();
            } else if (key == "media_type") {
                if (seen & 8u) r.refuse("duplicate_field");
                seen |= 8u;
                v.media_type = r.str();
            } else if (key == "call_id") {
                if (seen & 16u) r.refuse("duplicate_field");
                seen |= 16u;
                v.call_id = r.str();
            } else if (key == "name") {
                if (seen & 32u) r.refuse("duplicate_field");
                seen |= 32u;
                v.name = r.str();
            } else if (key == "arguments") {
                if (seen & 64u) r.refuse("duplicate_field");
                seen |= 64u;
                v.arguments = r.str();
            } else {
                r.refuse("unknown_field");
            }
            r.skip_ws();
            if (r.at() != ',') break;
            ++r.pos;
        }
    }
    if (r.at() != '}') r.refuse("malformed");
    ++r.pos;
    --r.depth;
    if ((seen & 1u) != 1u) r.refuse("missing_field");
    if (wire_kind) {
        const auto parsed = parse_part_kind(*wire_kind);
        if (!parsed) r.refuse("bad_enum");
        v.kind = *parsed;
    }
    return v;
}

